function ClubsByRegion({clubs, t, DIM, SILVER, BORDER, setSelectedClub, lang}) {
  const isEn = lang === "en";
  const featured = clubs.filter(c => !c.basic).slice(0, 3);
  const rest = clubs.filter(c => !featured.includes(c));
  const ORDER = ["מרכז","שרון","ירושלים","דרום","צפון"];
  const groups = ORDER.map(r => ({region:r, items: rest.filter(c => c.region === r)})).filter(g => g.items.length > 0);
  const other = rest.filter(c => !ORDER.includes(c.region));
  if (other.length) groups.push({region:"אחר", items: other});
  const [closed, setClosed] = useState({});
  const toggle = (r) => setClosed(o => ({...o, [r]: !o[r]}));

  return (
    <div>
      {featured.length > 0 && (
        <div style={{marginBottom:36}}>
          <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14}}>
            <span style={{color:"#e8c88a",fontSize:13,fontWeight:800,letterSpacing:2}}>★ {isEn?"FEATURED":"מועדונים מקודמים"}</span>
            <div style={{flex:1,height:1,background:"linear-gradient(90deg,rgba(200,169,110,0.35),transparent)"}}/>
          </div>
          <div className="g3">
            {featured.map((c,i) => <ClubCard key={"f"+i} c={c} t={t} DIM={DIM} SILVER={SILVER} BORDER={BORDER} setSelectedClub={setSelectedClub} />)}
          </div>
        </div>
      )}
      {groups.map((g,gi) => {
        const isOpen = !closed[g.region];
        return (
          <div key={gi} style={{marginBottom:26}}>
            <div onClick={()=>toggle(g.region)} style={{display:"flex",alignItems:"center",gap:10,marginBottom:14,cursor:"pointer",userSelect:"none"}}>
              <span style={{color:"#8fa3c0",fontSize:14,fontWeight:800,letterSpacing:1}}>{g.region} <span style={{color:DIM,fontWeight:400}}>({g.items.length})</span></span>
              <div style={{flex:1,height:1,background:`linear-gradient(90deg,${BORDER},transparent)`}}/>
              <span style={{color:DIM,fontSize:12,display:"inline-block",transform:isOpen?"rotate(180deg)":"none",transition:"transform .2s"}}>▾</span>
            </div>
            {isOpen && (
              <div className="g3">
                {g.items.map((c,i) => <ClubCard key={gi+"-"+i} c={c} t={t} DIM={DIM} SILVER={SILVER} BORDER={BORDER} setSelectedClub={setSelectedClub} />)}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function ClubMap3D({ clubs, onSelect, lang }){
  const isEn = lang==="en";
  const COORD = {
    "תל אביב":[32.083,34.781], "רמת גן":[32.070,34.824], "חולון":[32.015,34.773],
    "רמת השרון":[32.146,34.840], "בני ציון":[32.226,34.876], "אזור":[32.024,34.804],
    "מודיעין מכבים רעות":[31.898,35.010], "ירושלים":[31.768,35.214],
    "אשדוד":[31.792,34.641], "שדרות":[31.525,34.596], "הרצליה":[32.166,34.844],
    "נתניה":[32.328,34.858], "חדרה":[32.434,34.919], "קיסריה":[32.500,34.905],
    "זכרון יעקב":[32.573,34.953], "חיפה":[32.794,34.990], "קריית ביאליק":[32.836,35.083],
    "עכו":[32.928,35.075], "נהריה":[33.006,35.094], "כרמיאל":[32.916,35.296],
    "עפולה":[32.610,35.289], "נצרת":[32.702,35.298], "טבריה":[32.792,35.345],
    "באר שבע":[31.252,34.791], "אשקלון":[31.669,34.574], "ראשון לציון":[31.964,34.805],
    "פתח תקווה":[32.084,34.887], "כפר סבא":[32.175,34.907], "רעננה":[32.184,34.871],
    "רחובות":[31.894,34.809], "נשר":[32.767,35.043],
    "נס ציונה":[31.930,34.799], "סביון":[32.048,34.882], "גינוסר":[32.844,35.522],
  };
  const minLat=31.15, maxLat=33.10, minLng=34.45, maxLng=35.60;
  const seen={};
  const pins = clubs.map((c,i) => {
    const base = COORD[c.city] || [32.08,34.80];
    const n = (seen[c.city] = (seen[c.city]||0)+1) - 1;   // 0 for first in city
    const lat = base[0] + (n? (n%2? 0.010 : -0.010)*Math.ceil(n/2) : 0);
    const lng = base[1] + (n? (n%2? 0.014 : -0.014)*Math.ceil(n/2) : 0);
    const x = 14 + (lng-minLng)/(maxLng-minLng)*72;
    const y = 15 + (maxLat-lat)/(maxLat-minLat)*74;
    return { c, x, y, i };
  });
  // declutter — separate overlapping pins, but keep them anchored near true location
  const MIN = 13;
  pins.forEach(p => { p.ox = p.x; p.oy = p.y; });   // original (true) position
  for(let it=0; it<220; it++){
    for(let a=0;a<pins.length;a++){
      for(let b=a+1;b<pins.length;b++){
        let dx=pins[b].x-pins[a].x, dy=pins[b].y-pins[a].y;
        let d=Math.hypot(dx,dy);
        if(d<0.001){ dx=((a%2)?0.7:-0.7); dy=((b%2)?0.7:-0.7); d=Math.hypot(dx,dy); }
        if(d<MIN){
          const push=(MIN-d)/2*0.5, ux=dx/d, uy=dy/d;
          pins[a].x-=ux*push; pins[a].y-=uy*push;
          pins[b].x+=ux*push; pins[b].y+=uy*push;
        }
      }
    }
    // pull back toward true position so pins don't drift far from their real city
    pins.forEach(p => { p.x += (p.ox-p.x)*0.18; p.y += (p.oy-p.y)*0.18; });
    // clamp every iteration so nothing escapes the map
    pins.forEach(p => { p.x=Math.max(8,Math.min(92,p.x)); p.y=Math.max(13,Math.min(96,p.y)); });
  }
  return (
    <div style={{marginBottom:42}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12,flexWrap:"wrap",gap:8}}>
        <span style={{color:"#8fb0e0",fontSize:13}}>🗺️ {isEn?"Interactive 3D map — tap a pin to view & book a court":"מפה תלת-ממדית — לחצו על סימון לצפייה והזמנת מגרש"}</span>
        <span style={{color:"#4a6a88",fontSize:12}}>{clubs.length} {isEn?"clubs · Israel":"מועדונים · ישראל"}</span>
      </div>
      <div style={{perspective:"1100px",height:560,borderRadius:16,overflow:"hidden",position:"relative",
        border:"1px solid rgba(53,224,255,0.22)",background:"#050f22",
        boxShadow:"0 24px 60px rgba(0,0,0,0.45), inset 0 0 70px rgba(53,224,255,0.06)"}}>
        <div style={{position:"absolute",left:"-12%",right:"-12%",top:"-10%",bottom:"-34%",transformStyle:"preserve-3d",
          transform:"rotateX(52deg)",transformOrigin:"center 68%",
          background:"repeating-linear-gradient(0deg,transparent,transparent 30px,rgba(53,224,255,0.10) 30px,rgba(53,224,255,0.10) 31px), repeating-linear-gradient(90deg,transparent,transparent 30px,rgba(53,224,255,0.10) 30px,rgba(53,224,255,0.10) 31px)"}}>
          {/* coastline hint (west) */}
          <div style={{position:"absolute",left:0,top:0,bottom:0,width:"13%",background:"linear-gradient(90deg,rgba(24,70,130,0.5),transparent)",borderRight:"1px dashed rgba(120,180,255,0.25)"}}/>
        </div>

        {/* pins — flat layer above the tilted grid, so every pin stays clickable */}
        <div style={{position:"absolute",inset:0,zIndex:5}}>
          {pins.map(({c,x,y,i}) => (
            <button key={i} onClick={()=>onSelect(c)} title={c.name} aria-label={c.name}
              style={{position:"absolute",left:x+"%",top:y+"%",zIndex:100+Math.round(y),
                transform:"translate(-50%,-100%)",transformOrigin:"bottom center",
                background:"none",border:"none",cursor:"pointer",padding:0}}>
              <div style={{display:"flex",flexDirection:"column",alignItems:"center"}}>
                <div style={{background:"rgba(8,20,40,0.94)",border:"1px solid rgba(53,224,255,0.55)",borderRadius:10,
                  padding:"4px 9px",whiteSpace:"nowrap",boxShadow:"0 6px 16px rgba(0,0,0,0.55)",backdropFilter:"blur(2px)"}}>
                  <span style={{fontSize:14,marginInlineEnd:5}}>{c.image}</span>
                  <span style={{color:"#dce8ff",fontSize:11,fontWeight:700}}>{c.city}</span>
                </div>
                <div style={{width:0,height:0,borderLeft:"5px solid transparent",borderRight:"5px solid transparent",borderTop:"7px solid rgba(53,224,255,0.8)"}}/>
                <div style={{width:9,height:9,borderRadius:"50%",background:"#35e0ff",boxShadow:"0 0 14px #35e0ff",marginTop:-1}}/>
              </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

